using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 void TickCommunity(double dt){if(CoopClient||dungeon!=null)return;Community.Seed(game.World);TickCommunitySocial(dt);Community.TickEconomy(dt,game.Building.Pieces,(1+OperatingModule(4)/100.0)*(1+(JourneyEnabled?Community.Improvements*.05:0)));CatchUpCommunity(dt);SpawnCommunity();foreach(var n in Community.Survivors){if(n.State=="dead")continue;n.ShotTime=Math.Max(0,n.ShotTime-dt);if(n.Treatment>0){n.Treatment=Math.Max(0,n.Treatment-dt);n.Health=Math.Min(100,n.Health+dt*.7);n.Injury=Math.Max(0,n.Injury-dt*.25);}if(n.Downed){n.DownTime+=dt;if(n.Member&&n.DownTime>=ExpeditionCommunity.RescueWindow){LoseCommunityMember(n);continue;}if(!n.Member&&n.DownTime>=90){Vector3 refuge=Community.Established?Ground(Community.X,Community.Z):RescuePoint(n);n.X=refuge.X;n.Y=refuge.Y+.2;n.Z=refuge.Z;n.Health=20;n.Injury=85;n.Downed=false;n.DownTime=0;n.Owner="";if(communityAvatars.TryGetValue(n.Id,out var fallen)){fallen.Mover.Body.Position=NpcPoint(n);fallen.Mover.Path.Clear();}}else continue;}
   if(!communityAvatars.TryGetValue(n.Id,out var avatar))continue;var mover=avatar.Mover;var body=mover.Body;if(n.State=="trapped"){n.Pose="idle";continue;}string owner=n.Member?n.Owner:n.EscortOwner;var leader=CommunityLeader(owner);if(!string.IsNullOrEmpty(owner)&&leader==null){n.Owner="";n.EscortOwner="";}
   Vector3 target=body.Position;bool following=leader!=null;var bed=Community.Bed(n,game.Building.Pieces);if(following){target=leader.Value.Body.Position;float distance=Distance(target,body.Position);if(distance>70&&!(CoopHost?NearActiveSurface(body.Position,45):Distance(player.Position,body.Position)<45)&&!infected.Any(e=>Distance(e.Body.Position,target)<20)){var catchup=Ground(target.X+4,target.Z+4);if(OutdoorFree(catchup.X,catchup.Z)){body.Position=catchup;mover.Path.Clear();}}}
   else if(n.Member){double bx=bed?.X??Community.X,bz=bed?.Z??Community.Z;target=Ground(bx+(float)Math.Sin((int)(game.Clock/12)+n.Encounter)*2,bz+(float)Math.Cos((int)(game.Clock/12)+n.Encounter)*2);if(JourneyEnabled&&Community.Improvements>=2&&game.Hour>=18&&game.Hour<20&&Community.Food>0)target=Ground(Community.X+4+Math.Sin(n.Encounter*2.1)*1.8,Community.Z+4+Math.Cos(n.Encounter*2.1)*1.8);else if(JourneyEnabled&&n.Job=="guard")target=Ground(Community.X+Math.Sin(game.Clock*.025+n.Encounter)*7,Community.Z+Math.Cos(game.Clock*.025+n.Encounter)*7);if(bed!=null&&Distance(body.Position,new((float)bed.X,(float)bed.Y,(float)bed.Z))<5)target.Y=Math.Max(target.Y,(float)bed.Y);}
   bool atFire=CommunityGathering(n);if(atFire)target=CommunityFireSeat(n);
   Infected enemy=null;if(n.Member&&n.Injury<70&&(following||n.Job=="guard"))enemy=infected.Where(e=>!CheckpointPassive(e)&&!PassiveStoryEnemy(e)&&!Peaceful(e.Id)&&Distance(body.Position,e.Body.Position)<26*(1+WatchBonus(body.Position))).OrderBy(e=>Distance(body.Position,e.Body.Position)).FirstOrDefault(e=>CommunitySight(body,e));
   n.Pose="idle";if(enemy!=null){var aim=enemy.Body.Position-body.Position;body.Rotation=new(0,Mathf.Atan2(-aim.X,-aim.Z),0);if(n.ShotTime<=0){bool gun=Community.Ammo>0;float range=Distance(body.Position,enemy.Body.Position);if(gun||range<2.2){if(gun)Community.Ammo--;n.ShotTime=(gun?1.4:1.8)*(leader?.Game.CompanionAttack??1);n.Pose="shoot";double damage=(gun?14:8)*(leader?.Game.CompanionDamage??1)*(1+WatchBonus(body.Position))*(.5+n.Morale*.006)*(IsMillBoss(enemy.Id)?MillDamageMultiplier(enemy,enemy.Body.Position+Vector3.Up*2.3f):1);enemy.Hp-=damage;EnemyImpact(enemy,enemy.Body.Position+Vector3.Up,Vector3.Up,4);if(gun){EnemySound(body.Position,3);HearNoise(body.Position,70);CommunityTracer(body.Position+Vector3.Up*1.3f,enemy.Body.Position+Vector3.Up*(IsMillBoss(enemy.Id)?2.3f:1));}var credited=leader?.Game??(CoopHost?coopHostGame:game);if(IsMillBoss(enemy.Id))millParticipants.Add(credited);if(enemy.Hp<=0){var actor=CoopHost?coopActors.Values.FirstOrDefault(a=>a.Game==credited):null;if(actor!=null)WithCoopActor(actor,()=>KillEnemy(enemy));else KillEnemy(enemy);}}}if(Community.Ammo>0||Distance(body.Position,enemy.Body.Position)<2.2)target=body.Position;}
   var delta=target-body.Position;delta.Y=0;float stop=following?3:1.3f;var direction=delta.Length()>stop?PursuitDirection(mover,target,dt):Vector3.Zero;var velocity=direction.LengthSquared()>.01?direction.Normalized()*(following?(delta.Length()>12?7:4.6f):1.4f):Vector3.Zero;if(velocity.LengthSquared()>.1){n.Pose="walk";if(enemy==null)body.Rotation=new(0,Mathf.Atan2(-velocity.X,-velocity.Z),0);}else if(n.ShotTime>1)n.Pose="shoot";else if(atFire&&enemy==null){n.Pose="fireside";var face=CommunityFirePoint-body.Position;body.Rotation=new(0,Mathf.Atan2(-face.X,-face.Z),0);}else if(n.Member&&!following&&n.Job=="wood"&&n.Injury<70)n.Pose="wood";else if(n.Member&&!following&&n.Job=="supplies"&&n.Injury<70)n.Pose="supplies";velocity.Y=body.IsOnFloor()?-.1f:body.Velocity.Y-18*(float)dt;Vector3 before=body.Position;body.Velocity=velocity;body.MoveAndSlide();var horizontal=new Vector3(velocity.X,0,velocity.Z);if(horizontal.Length()>.2&&Distance(before,body.Position)<dt*.25&&body.IsOnFloor()){var raised=body.GlobalTransform.Translated(Vector3.Up*.6f);if(!body.TestMove(raised,horizontal*(float)dt)){body.GlobalPosition+=Vector3.Up*.6f;body.MoveAndSlide();}}if(body.Position.Y<game.World.Height(body.Position.X,body.Position.Z)-8)body.Position=Ground(body.Position.X,body.Position.Z)+Vector3.Up*.3f;n.X=body.Position.X;n.Y=body.Position.Y;n.Z=body.Position.Z;n.Yaw=body.Rotation.Y;
  }
 }
 bool CommunitySight(CharacterBody3D body,Infected enemy){var q=PhysicsRayQueryParameters3D.Create(body.Position+Vector3.Up*1.3f,enemy.Body.Position+Vector3.Up*(IsMillBoss(enemy.Id)?2.3f:1));q.Exclude=new(){body.GetRid()};var hit=GetWorld3D().DirectSpaceState.IntersectRay(q);return hit.Count>0&&hit["collider"].AsGodotObject()==enemy.Body;}
 void CommunityTracer(Vector3 from,Vector3 to){if(DisplayServer.GetName()=="headless"||impactBits.Count>150)return;var root=new Node3D();AddChild(root);Tube(root,from,to,.007f,new(1,.76f,.34f));impactBits.Add((root,Vector3.Zero,Time.GetTicksMsec()/1000.0+.08));}
 CampSurvivor ZombieCommunityTarget(Infected enemy,float playerDistance){if(dungeon!=null)return null;return Community.Survivors.Where(n=>n.State!="trapped"&&n.State!="dead"&&!n.Downed&&communityAvatars.ContainsKey(n.Id)&&Distance(enemy.Body.Position,NpcPoint(n))<Math.Min(22,playerDistance)).OrderBy(n=>Distance(enemy.Body.Position,NpcPoint(n))).FirstOrDefault(n=>{var q=PhysicsRayQueryParameters3D.Create(enemy.Body.Position+Vector3.Up*1.3f,NpcPoint(n)+Vector3.Up*1.1f);q.Exclude=new(){enemy.Body.GetRid()};var hit=GetWorld3D().DirectSpaceState.IntersectRay(q);return hit.Count>0&&hit["collider"].AsGodotObject()==communityAvatars[n.Id].Mover.Body;});}
 void HurtCommunity(CampSurvivor n,double damage){if(n.Downed||n.State is "trapped" or "dead")return;if(!string.IsNullOrEmpty(n.Owner)){game.World.Changes.Remember(n.Owner,n.Id,-2,"I was hurt following you. I need to feel safe again.");game.World.Changes.Remember(n.Owner,"home",-1,"Someone came home injured after following you.");}n.Health=Math.Max(0,n.Health-damage);n.Injury=Math.Min(100,n.Injury+damage*.6);n.Morale=Math.Max(5,n.Morale-3);if(n.Health<=0){n.Treatment=0;n.Downed=true;n.DownTime=0;n.Owner="";game.Notice=n.Name+(n.Member?" is down / FIRST AID within 3 active minutes or they will die":" is down / give first aid or let them recover at camp");}}
 void MillHurtCommunity(Infected boss,Vector3 origin,float radius,double damage,bool once){foreach(var n in Community.Survivors.Where(n=>n.State!="trapped"&&n.State!="dead"&&!n.Downed&&Distance(NpcPoint(n),origin)<radius)){if(!communityAvatars.TryGetValue(n.Id,out var a))continue;ulong id=a.Mover.Body.GetInstanceId();if(once&&!boss.BossHits.Add(id))continue;HurtCommunity(n,damage);}}
}
